// ---------------------------------------------------------------------------
// Lookup helpers

function normalizeName(s) {
	return String(s == null ? '' : s).toLowerCase()
		.replace(/&/g, 'and')
		.replace(/[^a-z0-9]+/g, ' ')
		.trim();
}

/** Public site URL for a playbook (by bot key, e.g. "Fox"), or null. */
function playbookUrl(key) {
	return PLAYBOOK_URL[key] || null;
}

/** Deep-link to a playbook background section, or the playbook page. */
function backgroundUrl(playbookKey, backgroundName) {
	const a = PLAYBOOK_ANCHORS[playbookKey];
	if (a && a.backgrounds && a.backgrounds[backgroundName]) return a.backgrounds[backgroundName];
	return playbookUrl(playbookKey);
}

/** Deep-link to a playbook instinct section, or the playbook page. */
function instinctUrl(playbookKey) {
	const a = PLAYBOOK_ANCHORS[playbookKey];
	return (a && a.instinct) || playbookUrl(playbookKey);
}

/** Deep-link to a playbook moves section, or the playbook page. */
function playbookMovesUrl(playbookKey) {
	const a = PLAYBOOK_ANCHORS[playbookKey];
	return (a && a.moves) || playbookUrl(playbookKey);
}

/** Site URL for a move. Prefers the playbook-scoped page when known. */
function moveUrl(name, playbookKey) {
	const n = normalizeName(name);
	if (playbookKey && PLAYBOOK_MOVE_URL[`${playbookKey}::${n}`]) return PLAYBOOK_MOVE_URL[`${playbookKey}::${n}`];
	return CORE_MOVE_URL[n] || PLAYBOOK_MOVE_ANY[n] || null;
}

/** Site URL for a trait (the primer trait list), or null. */
function traitUrl(name) {
	return name ? TRAIT_LIST_URL : null;
}

/** Site URL for an insert by name, or null. */
function insertUrlFor(name) { return INSERT_URL[normalizeName(name)] || null; }
/** Site URL for an arcanum by name, or null. */
function arcanaUrlFor(name) { return ARCANA_URL[normalizeName(name)] || null; }
/** Site URL for a gear/coin entry by name, or null. */
function gearUrlFor(name) { return GEAR_URL[normalizeName(name)] || null; }

module.exports = {
	BASE, HOW_TO_PLAY_URL, TRAIT_LIST_URL,
	PLAYBOOK_URL, PLAYBOOK_ANCHORS, CORE_MOVE_URL, PLAYBOOK_MOVE_URL, PLAYBOOK_MOVE_ANY,
	INSERT_URL, ARCANA_URL, GEAR_URL, SETTING_URL, STEADING_URL,
	normalizeName, playbookUrl, backgroundUrl, instinctUrl, playbookMovesUrl, moveUrl, traitUrl,
	insertUrlFor, arcanaUrlFor, gearUrlFor,
};
